using System; using System.Data; using System.Data.SQLite; using System.Drawing; using System.Windows.Forms; using ClinicQueueSystem.Data; using ClinicQueueSystem.Services;
namespace ClinicQueueSystem.Forms
{
 public class MainForm:Form
 {
  int uid; string role,name; ComboBox dept,doctor,shift,counter; NumericUpDown price; Label next,clock; Timer timer; Button print,admin;
  public MainForm(int userId,string userRole,string fullName){uid=userId;role=userRole;name=fullName; Text=Database.Setting("clinic_name","Clinic")+" - Queue Counter"; WindowState=FormWindowState.Maximized; MinimumSize=new Size(900,600); Build(); LoadData(); }
  void Build(){var top=new Panel{Dock=DockStyle.Top,Height=70,Padding=new Padding(15)}; Controls.Add(top); clock=new Label{Dock=DockStyle.Right,Width=220,TextAlign=ContentAlignment.MiddleRight,Font=new Font("Segoe UI",11)};top.Controls.Add(clock);var who=new Label{Text="User: "+name,AutoSize=true,Top=12,Left=15,Font=new Font("Segoe UI",10)};top.Controls.Add(who);admin=new Button{Text="ADMIN",Width=100,Height=34,Left=230,Top=8};admin.Visible=role=="ADMIN"||role=="SUPERVISOR";admin.Click+=(s,e)=>{using(var f=new AdminForm(uid,role))f.ShowDialog();LoadData();};top.Controls.Add(admin);var logout=new Button{Text="LOGOUT",Width=100,Height=34,Left=340,Top=8};logout.Click+=(s,e)=>Close();top.Controls.Add(logout);
   var p=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(30),ColumnCount=2,RowCount=8};p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,60));Controls.Add(p);p.Controls.Add(L("Department"),0,0);dept=C("Department",0);p.Controls.Add(dept,1,0);p.Controls.Add(L("Doctor"),0,1);doctor=C("Doctor",1);p.Controls.Add(doctor,1,1);p.Controls.Add(L("Shift"),0,2);shift=C("Shift",2);p.Controls.Add(shift,1,2);p.Controls.Add(L("Counter"),0,3);counter=C("Counter",3);p.Controls.Add(counter,1,3);p.Controls.Add(L("Fee"),0,4);price=new NumericUpDown{Minimum=0,Maximum=1000000,DecimalPlaces=2,Font=new Font("Segoe UI",14),Dock=DockStyle.Fill};p.Controls.Add(price,1,4);next=new Label{Text="NEXT: --",Dock=DockStyle.Fill,Font=new Font("Segoe UI",30,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter};p.Controls.Add(next,0,5);p.SetColumnSpan(next,2);print=new Button{Text="PRINT TICKET",Dock=DockStyle.Fill,Height=90,Font=new Font("Segoe UI",22,FontStyle.Bold)};print.Click+=PrintTicket;p.Controls.Add(print,0,6);p.SetColumnSpan(print,2);var info=new Label{Text="Independent sequence per Department + Shift. New day and new shift start at 001.",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter};p.Controls.Add(info,0,7);p.SetColumnSpan(info,2);
   dept.SelectedIndexChanged+=(s,e)=>{LoadDoctors();SetPrice();UpdateNext();};shift.SelectedIndexChanged+=(s,e)=>UpdateNext();timer=new Timer{Interval=1000};timer.Tick+=(s,e)=>{clock.Text=DateTime.Now.ToString("dd-MM-yyyy  hh:mm:ss tt");if(Database.Setting("auto_shift","1")=="1")AutoShift();};timer.Start(); }
  Label L(string x){return new Label{Text=x,AutoSize=true,Font=new Font("Segoe UI",13,FontStyle.Bold),Anchor=AnchorStyles.Left};} ComboBox C(string x,int i){return new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Font=new Font("Segoe UI",14),Dock=DockStyle.Fill,Tag=i};}
  void LoadData(){Fill(dept,"SELECT id,code||' - '||name name FROM departments WHERE active=1 ORDER BY display_order,id");Fill(shift,"SELECT id,name FROM shifts WHERE active=1 ORDER BY display_order,id");Fill(counter,"SELECT id,counter_number||' - '||name name FROM counters WHERE active=1 ORDER BY counter_number");LoadDoctors();SetPrice();AutoShift();UpdateNext();}
  void Fill(ComboBox b,string sql){var dt=new DataTable();using(var c=Database.Open())using(var a=new SQLiteDataAdapter(sql,c))a.Fill(dt);b.DataSource=dt;b.DisplayMember="name";b.ValueMember="id";}
  void LoadDoctors(){if(dept.DataSource==null)return;var dt=new DataTable();using(var c=Database.Open())using(var a=new SQLiteDataAdapter("SELECT d.id,d.name FROM doctors d JOIN doctor_departments dd ON dd.doctor_id=d.id AND dd.active=1 WHERE d.active=1 AND dd.department_id="+Convert.ToInt32(dept.SelectedValue)+" ORDER BY d.name",c))a.Fill(dt);var row=dt.NewRow();row["id"]=0;row["name"]="No specific doctor";dt.Rows.InsertAt(row,0);doctor.DataSource=dt;doctor.DisplayMember="name";doctor.ValueMember="id";}
  void SetPrice(){if(dept.SelectedValue==null)return;using(var c=Database.Open()){var v=Database.Scalar(c,"SELECT default_price FROM departments WHERE id=@id",new SQLiteParameter("@id",Convert.ToInt32(dept.SelectedValue)));if(v!=null)price.Value=Math.Min(price.Maximum,Convert.ToDecimal(v));}}
  void AutoShift(){if(shift.DataSource==null)return;int id=QueueService.GetCurrentShiftId();if(id>0)shift.SelectedValue=id;}
  void UpdateNext(){if(dept.SelectedValue==null||shift.SelectedValue==null)return;var d=Convert.ToInt32(dept.SelectedValue);var s=Convert.ToInt32(shift.SelectedValue);using(var c=Database.Open()){var v=Database.Scalar(c,"SELECT COALESCE(last_number,0)+1 FROM sequence_counters WHERE sequence_date=@d AND shift_id=@s AND department_id=@dep",new SQLiteParameter("@d",DateTime.Now.ToString("yyyy-MM-dd")),new SQLiteParameter("@s",s),new SQLiteParameter("@dep",d));using(var cmd=new SQLiteCommand("SELECT code FROM departments WHERE id=@id",c)){cmd.Parameters.AddWithValue("@id",d);var code=Convert.ToString(cmd.ExecuteScalar());next.Text="NEXT: "+code+(Convert.ToInt32(v??1)).ToString("000");}}}
  void PrintTicket(object s,EventArgs e){try{var t=QueueService.Issue(Convert.ToInt32(dept.SelectedValue),Convert.ToInt32(doctor.SelectedValue),Convert.ToInt32(shift.SelectedValue),Convert.ToInt32(counter.SelectedValue),uid,price.Value);string printer="";using(var c=Database.Open())using(var cmd=new SQLiteCommand("SELECT p.system_printer_name FROM counters c LEFT JOIN printers p ON p.id=c.printer_id WHERE c.id=@id",c)){cmd.Parameters.AddWithValue("@id",Convert.ToInt32(counter.SelectedValue));printer=Convert.ToString(cmd.ExecuteScalar());}EscPosPrinter.Print(t,printer);UpdateNext();}catch(Exception ex){MessageBox.Show(ex.Message,"Ticket",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 }
}
